"""Conflicts confined to generated files, settled by the host without a fixer turn (#551).

The loop file's ``generated`` list names, per entry, the repo-relative paths a command
regenerates (``config.check_generated``). When the host's merge of the base into a PR head
conflicts **only** in registered paths, ``regenerate`` runs each affected entry's command in the
sandbox (``contained.run``: no model, no tokens, no network) on the merged tree *as it is*, markers
included: the generator rewrites what it owns, so a conflict inside a generated block disappears
and a conflict in hand-written prose leaves its markers behind.

The host reads back only the registered paths' bytes (stdout, so a cap applies) and ignores
anything else the sandbox wrote. Any failure returns ``None`` after logging why, and the caller
launches the normal conflict turn: the shortcut is never a stall.
"""
from __future__ import annotations

import base64
import binascii
import hashlib
import subprocess
import tempfile
from pathlib import Path

from . import config, contained, safe_push, trusted_fetch, util

GENERATE_TIMEOUT_S = 120
FILE_MAX = safe_push.MAX_FILE          # per registered file, as a push carries it
TOTAL_MAX = safe_push.MAX_CONTENT

# Runs the command (its own output to stderr), then prints "<path> <base64>" per registered path.
# A missing or unreadable path fails the whole run.
WRAPPER = ('cmd=$1; shift; sh -c "$cmd" >&2 || exit 1; '
           'for p in "$@"; do printf "%s %s\\n" "$p" "$(base64 -w0 < "$p")" || exit 1; done')


def conflicted_entries(loop: dict, conflicted: list[str]) -> list[dict] | None:
    """The ``generated`` entries holding the conflicted paths, or ``None`` when the shortcut does
    not apply: it is off, nothing conflicts, or a conflicted path is not registered."""
    entries = config.generated(loop)
    registered = {path for entry in entries for path in entry["paths"]}
    if not entries or not conflicted or not set(conflicted) <= registered:
        return None
    return [entry for entry in entries if set(entry["paths"]) & set(conflicted)]


def _parse(stdout: str, paths: list[str]) -> dict[str, bytes]:
    out: dict[str, bytes] = {}
    for line in stdout.splitlines():
        name, _, encoded = line.partition(" ")
        if name in paths and name not in out:        # anything else on stdout is ignored
            try:
                out[name] = base64.b64decode(encoded, validate=True)
            except (ValueError, binascii.Error):
                raise ValueError(f"unreadable output for {name}") from None
    if set(out) != set(paths):
        raise ValueError(f"no output for {', '.join(sorted(set(paths) - set(out)))}")
    return out


def regenerate(loop: dict, merged: dict, settings: dict, *, work_root) -> dict[str, bytes] | None:
    """The regenerated bytes (path -> content) to push for ``merged``, or ``None`` to fall back
    to a fixer turn (the reason is logged)."""
    entries = conflicted_entries(loop, merged["conflicted"])
    if entries is None:
        if config.generated(loop) and merged["conflicted"]:
            util.log("generated files: a conflicted path is not registered; normal conflict turn")
        return None
    from . import trusted_turn
    try:
        Path(work_root).mkdir(mode=0o700, parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix="gen-", dir=work_root) as tmp:
            root = Path(tmp)
            code, home, export = root / "code", root / "home", root / "export"
            home.mkdir(mode=0o700)
            export.mkdir(mode=0o700)
            checkout = export / "repo"
            checkout.mkdir(mode=0o700)
            trusted_turn._safe_code_snapshot(Path(settings["source"]), code)
            trusted_fetch._extract(merged["archive"], checkout, merged["entries"],
                                   frozenset(merged["skipped"]))
            query = root / "query.txt"
            query.write_text("regenerate generated files\n")
            before = {path: (checkout / path).read_bytes() if (checkout / path).is_file() else None
                      for entry in entries for path in entry["paths"]}
            result: dict[str, bytes] = {}
            for entry in entries:
                run = contained.run(
                    code=code, venv=Path(settings["venv"]), runtime=Path(settings["runtime"]),
                    home=home, checkout=checkout, rust=Path(settings["rust"]), query=query,
                    entry=["/bin/sh", "-c", WRAPPER, "sh", entry["command"], *entry["paths"]],
                    timeout=GENERATE_TIMEOUT_S)
                if run.returncode:
                    raise ValueError(f"`{entry['command'][:80]}` exited {run.returncode}")
                result.update(_parse(run.stdout, entry["paths"]))
    except subprocess.TimeoutExpired:
        util.log(f"generated files: the generator timed out after {GENERATE_TIMEOUT_S}s; "
                 "normal conflict turn")
        return None
    except Exception as exc:                       # a fallback, never a stall
        util.log(f"generated files: regeneration failed ({type(exc).__name__}: {exc}); "
                 "normal conflict turn")
        return None
    if any(safe_push.CONFLICT_MARKER.search(data) for data in result.values()):
        util.log("generated files: conflict markers remain after regeneration; "
                 "normal conflict turn")
        return None
    # The conflicted paths always go; a sibling path goes only if the generator changed it.
    files = {path: data for path, data in result.items()
             if path in merged["conflicted"] or data != before.get(path)}
    if (any(len(data) > FILE_MAX for data in files.values())
            or sum(len(data) for data in files.values()) > TOTAL_MAX):
        util.log("generated files: regenerated output is over the size cap; normal conflict turn")
        return None
    return files


def manifest(head: str, base_ref: str, files: dict[str, bytes]) -> dict:
    """The push manifest for ``files``: host-written, in the shape ``safe_push._manifest`` checks."""
    return {"base_head": head,
            "message": f"Merge {base_ref}; regenerate {', '.join(sorted(files))}",
            "files": [{"path": path, "content_b64": base64.b64encode(data).decode(),
                       "sha256": hashlib.sha256(data).hexdigest()}
                      for path, data in sorted(files.items())]}
